mapper.select:
SELECT F.*
FROM wimb.common_file F
WHERE F.file_id     = #{fileId}
 AND  F.file_seq_no = #{fileSeqNo}
 AND  F.user_id     = #{userId}
 AND  F.identifier  = #{identifier}
 AND  F.status      = #{status}

