     , #{file.originalFileName}
     , #{file.size}
     , #{file.contentType}
     , #{file.identifier}
     , #{file.s3Key}
     , #{file.representYn}
     , #{file.startedAt}
     , #{file.uploadedAt}
     , #{file.updatedAt}
